  249	    static final class Pix implements PaymentMethod {
  250	        public String code() { return "PIX"; }
  251	
  252	        public boolean acceptsInstallments(int n) { return n == 1; }
  253	
  254	        public boolean availableFor(BigDecimal total) { return true; }
  255	
  256	        public PaymentOutcome settle(BigDecimal total, int n, boolean couponUsed) {
  257	            BigDecimal result = couponUsed ? total : total.subtract(Money.percent(total, "0.05"));
  258	            return new PaymentOutcome(result, result);
  259	        }
  260	    }
  261	
  262	    static final class BankSlip implements PaymentMethod {
  263	        private static final BigDecimal FEE = new BigDecimal("3.49");
  264	        private static final BigDecimal MAX_TOTAL = new BigDecimal("1000.00");
  265	
  266	        public String code() { return "BANK_SLIP"; }
  267	
  268	        public boolean acceptsInstallments(int n) { return n == 1; }
  269	
  270	        public boolean availableFor(BigDecimal total) { return total.compareTo(MAX_TOTAL) <= 0; }
  271	
  272	        public PaymentOutcome settle(BigDecimal total, int n, boolean couponUsed) {
  273	            BigDecimal result = total.add(FEE);
  274	            return new PaymentOutcome(result, result);
  275	        }
  276	    }
  277	
  278	    static final class CreditCard implements PaymentMethod {
  279	        private static final int MAX_INTEREST_FREE = 3;
  280	        private static final BigDecimal MONTHLY_RATE = new BigDecimal("0.0199");
  281	        private static final MathContext MC = new MathContext(40);
  282	
  283	        public String code() { return "CREDIT_CARD"; }
  284	
  285	        public boolean acceptsInstallments(int n) { return n >= 1 && n <= 12; }
  286	
  287	        public boolean availableFor(BigDecimal total) { return true; }
  288	
  289	        public PaymentOutcome settle(BigDecimal total, int n, boolean couponUsed) {
  290	            BigDecimal count = BigDecimal.valueOf(n);
  291	            if (n <= MAX_INTEREST_FREE) {
  292	                return new PaymentOutcome(total, total.divide(count, 2, RoundingMode.HALF_EVEN));
  293	            }
  294	            // Tabela Price: parcela = total * i / (1 - (1 + i)^-n)
  295	            BigDecimal growth = BigDecimal.ONE.add(MONTHLY_RATE).pow(n, MC);
  296	            BigDecimal denominator = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(growth, MC), MC);
  297	            BigDecimal installment = Money.round(total.multiply(MONTHLY_RATE).divide(denominator, MC));
  298	            return new PaymentOutcome(installment.multiply(count), installment);
  299	        }
  300	    }
  301	}
