  1	package shop;
  2	
  3	import java.math.BigDecimal;
  4	import java.util.ArrayList;
  5	import java.util.HashMap;
  6	import java.util.HashSet;
  7	import java.util.List;
  8	import java.util.Map;
  9	import java.util.Set;
 10	import java.util.regex.Pattern;
 11	
 12	/** Único lugar onde o resumo é calculado: o resumo e o registro do pedido passam por aqui. */
 13	class PricingService {
 14	    private static final Pattern ZIP = Pattern.compile("\\d{8}");
 15	
 16	    private final ShippingMethods shipping;
 17	    private final Coupons coupons;
 18	    private final PaymentMethods payments;
 19	
 20	    PricingService(ShippingMethods shipping, Coupons coupons, PaymentMethods payments) {
 21	        this.shipping = shipping;
 22	        this.coupons = coupons;
 23	        this.payments = payments;
 24	    }
 25	
 26	    Summary calculate(CheckoutRequest r, Tx tx) {
 27	        List<CartLine> lines = loadCart(r, tx);
 28	
 29	        ClubTier tier = ClubTier.parse(r.clubTier());
 30	        if (tier == null) throw ApiException.unprocessable("INVALID_CLUB_TIER");
 31	        Region region = Region.parse(r.region());
 32	        if (region == null) throw ApiException.unprocessable("INVALID_REGION");
 33	        if (r.zipCode() == null || !ZIP.matcher(r.zipCode()).matches()) {
 34	            throw ApiException.unprocessable("INVALID_ZIP_CODE");
 35	        }
 36	        ShippingMethod method = shipping.get(r.shippingMethod());
 37	        if (method == null) throw ApiException.unprocessable("INVALID_SHIPPING_METHOD");
 38	
 39	        BigDecimal subtotal = BigDecimal.ZERO;
 40	        BigDecimal weight = BigDecimal.ZERO;
 41	        for (CartLine l : lines) {
 42	            subtotal = subtotal.add(l.total());
 43	            weight = weight.add(l.product().weightKg().multiply(BigDecimal.valueOf(l.quantity())));
 44	        }
 45	        subtotal = Money.round(subtotal);
 46	
 47	        ShippingQuote quote = method.quote(new ShippingContext(r.zipCode(), weight, region));
 48	        BigDecimal shippingCost = tier.waivesShipping() && method.waivableByClub() ? Money.ZERO : quote.cost();
 49	
 50	        BigDecimal couponDiscount = Money.ZERO;
 51	        if (r.couponPresent()) {
 52	            Coupon coupon = coupons.get(r.coupon());
 53	            if (coupon == null) throw ApiException.unprocessable("INVALID_COUPON");
 54	            CouponContext ctx = new CouponContext(lines, subtotal, shippingCost, method,
 55	                    () -> !tx.hasFulfilledOrder(r.cpf()));
 56	            couponDiscount = coupons.discountFor(coupon, ctx);
 57	        }
 58	
 59	        BigDecimal insurance = region.insurance(subtotal);
 60	        BigDecimal orderTotal = Money.round(subtotal.subtract(couponDiscount).add(shippingCost).add(insurance));
 61	
 62	        PaymentMethod payment = payments.get(r.paymentMethod());
 63	        if (payment == null) throw ApiException.unprocessable("INVALID_PAYMENT_METHOD");
 64	        if (!payment.acceptsInstallments(r.installments())) throw ApiException.unprocessable("INVALID_INSTALLMENTS");
 65	        if (!payment.availableFor(orderTotal)) throw ApiException.unprocessable("PAYMENT_METHOD_UNAVAILABLE");
 66	        PaymentOutcome outcome = payment.settle(orderTotal, r.installments(), r.couponPresent());
 67	        BigDecimal finalTotal = Money.round(outcome.finalTotal());
 68	
 69	        return new Summary(subtotal, couponDiscount, shippingCost, quote.days(), insurance,
 70	                finalTotal.subtract(orderTotal), finalTotal, r.installments(), outcome.installmentAmount(),
 71	                tier.credit(subtotal), tier.gift(subtotal));
 72	    }
 73	
 74	    private List<CartLine> loadCart(CheckoutRequest r, Tx tx) {
 75	        if (r.cpf() == null || r.cpf().isBlank() || r.email() == null || r.email().isBlank()
 76	                || r.items().isEmpty()) {
 77	            throw ApiException.unprocessable("INVALID_ORDER");
 78	        }
 79	        Set<String> seen = new HashSet<>();
 80	        for (CheckoutRequest.RawItem i : r.items()) {
 81	            if (i.sku() == null || i.sku().isBlank() || i.quantity() == null || i.quantity() <= 0
 82	                    || !seen.add(i.sku())) {
 83	                throw ApiException.unprocessable("INVALID_ORDER");
 84	            }
 85	        }
 86	        Map<String, Product> products = new HashMap<>();
 87	        for (CheckoutRequest.RawItem i : r.items()) {
 88	            Product p = tx.findProduct(i.sku()).orElseThrow(() -> ApiException.unprocessable("UNKNOWN_PRODUCT"));
 89	            products.put(i.sku(), p);
 90	        }
 91	        for (Product p : products.values()) {
 92	            if (p.discontinued()) throw ApiException.unprocessable("PRODUCT_DISCONTINUED");
 93	        }
 94	        List<CartLine> lines = new ArrayList<>();
 95	        for (CheckoutRequest.RawItem i : r.items()) {
 96	            Product p = products.get(i.sku());
 97	            if (p.stock() < i.quantity()) throw ApiException.unprocessable("INSUFFICIENT_STOCK");
 98	            lines.add(new CartLine(p, i.quantity()));
 99	        }
100	        return lines;
101	    }
102	}
  1	package shop;
  2	
  3	import java.time.Clock;
  4	import java.time.Duration;
  5	import java.time.Instant;
  6	import java.time.format.DateTimeParseException;
  7	import java.time.temporal.ChronoUnit;
  8	import java.util.List;
  9	import java.util.UUID;
 10	
 11	class OrderService {
 12	    private static final Duration PAYMENT_WINDOW = Duration.ofHours(48);
 13	
 14	    private final Store store;
 15	    private final PricingService pricing;
 16	    private final Clock clock;
 17	    private final List<OrderEffect> effects = List.of(new StockEffect(), new ClubCreditEffect(), new NotificationEffect());
 18	
 19	    OrderService(Store store, PricingService pricing, Clock clock) {
 20	        this.store = store;
 21	        this.pricing = pricing;
 22	        this.clock = clock;
 23	    }
 24	
 25	    Summary summary(CheckoutRequest request) {
 26	        return store.transaction(tx -> pricing.calculate(request, tx));
 27	    }
 28	
 29	    Order register(CheckoutRequest request) {
 30	        return store.transaction(tx -> {
 31	            Summary summary = pricing.calculate(request, tx);
 32	            List<OrderItem> items = request.items().stream()
 33	                    .map(i -> new OrderItem(i.sku(), i.quantity())).toList();
 34	            Order order = new Order(UUID.randomUUID().toString(), request.cpf(), request.email(),
 35	                    OrderStatus.AWAITING_PAYMENT, clock.instant().truncatedTo(ChronoUnit.SECONDS), summary, items,
 36	                    null, null, null);
 37	            tx.ensureCustomer(request.cpf(), request.email());
 38	            tx.insertOrder(order);
 39	            return order;
 40	        });
 41	    }
 42	
 43	    Order get(String id) {
 44	        return store.transaction(tx -> tx.findOrder(id).orElseThrow(OrderService::notFound));
 45	    }
 46	
 47	    /** Resultado de uma transação que pode ter confirmado algo e mesmo assim recusar o pedido. */
 48	    private record Outcome(Order order, ApiException error) {}
 49	
 50	    Order pay(String id, String transactionId, String paidAtText) {
 51	        Outcome outcome = store.transaction(tx -> {
 52	            Order order = tx.lockOrder(id).orElseThrow(OrderService::notFound);
 53	            Instant paidAt = parseInstant(paidAtText);
 54	            if (transactionId == null || transactionId.isBlank() || paidAt == null) {
 55	                throw ApiException.unprocessable("INVALID_ORDER");
 56	            }
 57	            PaymentRecord previous = tx.findPayment(id, transactionId).orElse(null);
 58	            if (previous != null) {
 59	                return previous.errorCode() == null
 60	                        ? new Outcome(order, null)
 61	                        : new Outcome(null, new ApiException(previous.errorCode(), previous.httpStatus()));
 62	            }
 63	            if (order.status() != OrderStatus.AWAITING_PAYMENT) throw ApiException.conflict("OPERATION_NOT_ALLOWED");
 64	
 65	            if (paidAt.isAfter(order.createdAt().plus(PAYMENT_WINDOW))) {
 66	                return reject(tx, order, transactionId, "ORDER_EXPIRED");
 67	            }
 68	            try {
 69	                for (OrderEffect e : effects) e.onPaid(tx, order);
 70	            } catch (ApiException e) {
 71	                return reject(tx, order, transactionId, e.code());
 72	            }
 73	            Order paid = order.paid(transactionId, paidAt);
 74	            tx.updateOrder(paid);
 75	            tx.savePayment(id, transactionId, new PaymentRecord(null, 200));
 76	            return new Outcome(paid, null);
 77	        });
 78	        if (outcome.error() != null) throw outcome.error();
 79	        return outcome.order();
 80	    }
 81	
 82	    private Outcome reject(Tx tx, Order order, String transactionId, String code) {
 83	        cancelInTx(tx, order, false);
 84	        tx.savePayment(order.id(), transactionId, new PaymentRecord(code, 409));
 85	        return new Outcome(null, ApiException.conflict(code));
 86	    }
 87	
 88	    Order ship(String id, String trackingCode) {
 89	        return store.transaction(tx -> {
 90	            Order order = tx.lockOrder(id).orElseThrow(OrderService::notFound);
 91	            if (trackingCode == null || trackingCode.isBlank()) throw ApiException.unprocessable("INVALID_ORDER");
 92	            if (order.status() != OrderStatus.PAID) throw ApiException.conflict("OPERATION_NOT_ALLOWED");
 93	            Order shipped = order.shipped(trackingCode);
 94	            tx.updateOrder(shipped);
 95	            for (OrderEffect e : effects) e.onShipped(tx, shipped);
 96	            return shipped;
 97	        });
 98	    }
 99	
100	    Order deliver(String id) {
101	        return store.transaction(tx -> {
102	            Order order = tx.lockOrder(id).orElseThrow(OrderService::notFound);
103	            if (order.status() != OrderStatus.SHIPPED) throw ApiException.conflict("OPERATION_NOT_ALLOWED");
104	            Order delivered = order.withStatus(OrderStatus.DELIVERED);
105	            tx.updateOrder(delivered);
106	            return delivered;
107	        });
108	    }
109	
110	    Order cancel(String id) {
111	        return store.transaction(tx -> {
112	            Order order = tx.lockOrder(id).orElseThrow(OrderService::notFound);
113	            if (order.status() != OrderStatus.AWAITING_PAYMENT && order.status() != OrderStatus.PAID) {
114	                throw ApiException.conflict("OPERATION_NOT_ALLOWED");
115	            }
116	            return cancelInTx(tx, order, order.status() == OrderStatus.PAID);
117	        });
118	    }
119	
120	    private Order cancelInTx(Tx tx, Order order, boolean wasPaid) {
121	        Order cancelled = order.withStatus(OrderStatus.CANCELLED);
122	        if (wasPaid) {
123	            for (OrderEffect e : effects) e.onPaidOrderCancelled(tx, order);
124	        }
125	        tx.updateOrder(cancelled);
126	        for (OrderEffect e : effects) e.onCancelled(tx, cancelled);
127	        return cancelled;
128	    }
129	
130	    private static Instant parseInstant(String text) {
131	        if (text == null) return null;
132	        try {
133	            return Instant.parse(text);
134	        } catch (DateTimeParseException e) {
135	            return null;
136	        }
137	    }
138	
139	    private static ApiException notFound() {
140	        return ApiException.notFound("ORDER_NOT_FOUND");
141	    }
142	}
  1	package shop;
  2	
  3	import com.fasterxml.jackson.databind.JsonNode;
  4	
  5	import java.util.ArrayList;
  6	import java.util.List;
  7	
  8	/** Dados da compra, lidos do JSON sem rejeitar nada: a conferência (e a ordem dos erros) fica no cálculo. */
  9	record CheckoutRequest(String cpf, String email, List<RawItem> items, String zipCode, String region,
 10	                       String shippingMethod, boolean couponPresent, String coupon, String paymentMethod,
 11	                       int installments, String clubTier) {
 12	
 13	    /** sku ou quantity nulos indicam valor ausente ou inválido. */
 14	    record RawItem(String sku, Integer quantity) {}
 15	
 16	    static final int INVALID_INSTALLMENTS = -1;
 17	
 18	    static CheckoutRequest parse(JsonNode root) {
 19	        JsonNode body = root != null && root.isObject() ? root : Json.MAPPER.createObjectNode();
 20	        JsonNode customer = body.path("customer");
 21	        List<RawItem> items = new ArrayList<>();
 22	        JsonNode itemsNode = body.path("items");
 23	        if (itemsNode.isArray()) {
 24	            for (JsonNode n : itemsNode) {
 25	                String sku = n.isObject() ? text(n.get("sku")) : null;
 26	                JsonNode q = n.isObject() ? n.get("quantity") : null;
 27	                Integer quantity = q != null && q.isIntegralNumber() && q.canConvertToInt() ? q.asInt() : null;
 28	                items.add(new RawItem(sku, quantity));
 29	            }
 30	        }
 31	        JsonNode couponNode = body.get("coupon");
 32	        boolean couponPresent = couponNode != null && !couponNode.isNull();
 33	        JsonNode inst = body.get("installments");
 34	        int installments;
 35	        if (inst == null || inst.isNull()) installments = 1;
 36	        else if (inst.isIntegralNumber() && inst.canConvertToInt()) installments = inst.asInt();
 37	        else installments = INVALID_INSTALLMENTS;
 38	        return new CheckoutRequest(
 39	                customer.isObject() ? text(customer.get("cpf")) : null,
 40	                customer.isObject() ? text(customer.get("email")) : null,
 41	                items, text(body.get("zipCode")), text(body.get("region")), text(body.get("shippingMethod")),
 42	                couponPresent, couponPresent ? couponNode.asText(couponNode.toString()) : null,
 43	                text(body.get("paymentMethod")), installments, text(body.get("clubTier")));
 44	    }
 45	
 46	    /** Texto do campo; valores que não são texto viram um texto que nunca é um código válido. */
 47	    private static String text(JsonNode n) {
 48	        if (n == null || n.isNull()) return null;
 49	        return n.isTextual() ? n.asText() : n.toString();
 50	    }
 51	}

