     1	package shop;
     2	
     3	import io.javalin.Javalin;
     4	
     5	import java.time.Clock;
     6	
     7	public final class Main {
     8	    private Main() {}
     9	
    10	    public static void main(String[] args) {
    11	        String portText = System.getenv("PORT");
    12	        int port = portText == null || portText.isBlank() ? 8080 : Integer.parseInt(portText.trim());
    13	
    14	        JdbcStore store = new JdbcStore(require("DB_URL"), System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
    15	        Javalin app = Api.create(store, new TransLogGateway(System.getenv("TRANSLOG_URL")), Clock.systemUTC());
    16	        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
    17	            app.stop();
    18	            store.close();
    19	        }));
    20	        app.start(port);
    21	    }
    22	
    23	    private static String require(String name) {
    24	        String value = System.getenv(name);
    25	        if (value == null || value.isBlank()) throw new IllegalStateException(name + " is not set");
    26	        return value;
    27	    }
    28	}
     1	package shop;
     2	
     3	import java.util.List;
     4	
     5	/**
     6	 * Consequências das mudanças de situação do pedido. Novas consequências (SMS, cashback...) são novas
     7	 * implementações adicionadas à lista em {@link OrderService}.
     8	 */
     9	interface OrderEffect {
    10	    /** Pagamento confirmado. Pode recusar (ApiException) desde que ainda não tenha alterado nada. */
    11	    default void onPaid(Tx tx, Order order) {}
    12	
    13	    /** Pedido já pago foi cancelado: desfaz o que {@link #onPaid} fez. */
    14	    default void onPaidOrderCancelled(Tx tx, Order order) {}
    15	
    16	    /** Qualquer cancelamento. */
    17	    default void onCancelled(Tx tx, Order order) {}
    18	
    19	    default void onShipped(Tx tx, Order order) {}
    20	}
    21	
    22	class StockEffect implements OrderEffect {
    23	    @Override
    24	    public void onPaid(Tx tx, Order order) {
    25	        List<String> skus = order.items().stream().map(OrderItem::sku).toList();
    26	        List<Product> locked = tx.lockProducts(skus);
